<?php require_once __DIR__.'/auth.php';require_admin();require_once __DIR__.'/../includes/admin_layout.php';$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$no='ST-'.date('ym').'-'.strtoupper(bin2hex(random_bytes(2)));$s=$pdo->prepare('INSERT INTO staff(staff_no,full_name,role,department_id,phone,email) VALUES(?,?,?,?,?,?)');$s->execute([$no,trim($_POST['full_name']),$_POST['role'],($_POST['department_id']??'')?:null,trim($_POST['phone']??''),trim($_POST['email']??'')]);flash('Staff member added.');redirect('doctors.php');}$deps=$pdo->query('SELECT id,name FROM departments ORDER BY name')->fetchAll();$rows=$pdo->query('SELECT s.*,d.name department FROM staff s LEFT JOIN departments d ON d.id=s.department_id ORDER BY s.full_name')->fetchAll();admin_header('Doctors & Staff','doctors.php');?><div class="pagehead"><div><h1>Doctors & Staff</h1><div class="muted">Clinical and support staff directory.</div></div><a class="btn" href="?action=new">Add staff</a></div><?php if(($_GET['action']??'')==='new'):?><div class="card" style="margin-bottom:18px"><form method="post"><?=csrf_field()?><div class="form-grid"><div class="field"><label>Full name</label><input name="full_name" required></div><div class="field"><label>Role</label><select name="role"><option>Doctor</option><option>Nurse</option><option>Midwife</option><option>Laboratory</option><option>Pharmacist</option><option>Administrator</option><option>Other</option></select></div><div class="field"><label>Department</label><select name="department_id"><option value="">None</option><?php foreach($deps as $d):?><option value="<?=$d['id']?>"><?=e($d['name'])?></option><?php endforeach;?></select></div><div class="field"><label>Phone</label><input name="phone"></div><div class="field"><label>Email</label><input type="email" name="email"></div></div><button style="margin-top:14px">Save staff</button></form></div><?php endif;?><div class="card table-wrap"><table class="table"><tr><th>Staff No.</th><th>Name</th><th>Role</th><th>Department</th><th>Phone</th><th>Email</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['staff_no'])?></td><td><?=e($r['full_name'])?></td><td><?=e($r['role'])?></td><td><?=e($r['department'])?></td><td><?=e($r['phone'])?></td><td><?=e($r['email'])?></td></tr><?php endforeach;?></table></div><?php admin_footer();
